delete from public.receta_insumos;
delete from public.recetas;
with rec as (insert into public.recetas (nombre_producto, categoria_carta, costo_total_calculado, margen_objetivo, precio_venta_sugerido) values ('Cocido, tybo, crema de palta en pan bagguetin', 'SANDWICHES', 2563.255683, 36, 10500) returning id) insert into public.receta_insumos (receta_id, insumo_id, cantidad_gramos) select rec.id, ins.id, g.gramos from rec, (values ('JAMON COCIDO DON ANTONINO', 90), ('TYBO LA PAULINA', 55), ('CREMA DE PALTA', 40), ('papas danal sazonadas', 25)) as g(nombre, gramos) join public.insumos ins on lower(ins.nombre) = lower(g.nombre);
